import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        a = read_ints()

        # Create a graph from the BFS order
        g = defaultdict(list)
        for i in range(1, n):
            g[a[i-1]].append(a[i])

        # The minimum height is determined by the longest path in the tree
        # Since BFS ensures that children are visited in ascending order,
        # the tree will be a straight line from the root to the farthest leaf
        # The height of the tree is the length of this path
        height = 0
        current_level = [1]
        while current_level:
            next_level = []
            for node in current_level:
                for child in g[node]:
                    next_level.append(child)
            current_level = next_level
            height += 1

        print(height)

if __name__ == "__main__":
    main()
